from science_v2.k import Unit
U = Unit("s7u02")

U.q("R", "2.1", "O1", "Which of these is NOT a physical quantity?", ("Colour", "Colour is described, not measured with a number and a unit."), [("Mass", "Mass is measured in kg."), ("Time", "Time is measured in s."), ("Length", "Length is measured in m.")])
U.q("E", "2.2", "O3", "Kim reads a ruler from an angle and gets 12.4 cm; her partner reads it straight on and gets 12.1 cm. Why do they differ?", ("Parallax error: Kim's eye was not level with the mark", "Read scales with your eye directly in line with the mark."), [("The ruler changed length", "The ruler did not change."), ("Kim's reading is more accurate", "Reading at an angle adds an error.")])
U.q("P", "2.2", "O2", "A ruler marked in mm is used to measure a pencil. What is the most precise reading it can give?", ("To the nearest 1 mm", "The smallest division sets the precision."), [("To the nearest 1 cm", "The ruler has mm marks, so it can do better."), ("To the nearest 0.01 mm", "The ruler has no marks that small.")])
U.q("R", "2.3", "O4", "Two rectangles each have a perimeter of 20 cm. Must they have the same area?", ("No", "A 9 cm × 1 cm rectangle has area 9 cm²; a 5 cm × 5 cm square has 25 cm²."), [("Yes", "Try 9 × 1 and 5 × 5."), ("Only if they are squares", "Different rectangles with the same perimeter can have different areas.")])
U.q("F", "2.4", "O5", "How can you find the volume of an irregular stone?", ("Lower it into a measuring cylinder of water and see how much the water level rises", "The rise in water level equals the stone's volume."), [("Measure its length, width and height and multiply", "That only works for cuboids."), ("Weigh it", "Weighing gives mass, not volume.")])
U.q("E", "2.5", "O6", "Sam says: 'My mass is less on the Moon.' Is he right?", ("No – his mass is the same; his weight is less", "Mass is the amount of matter; weight depends on gravity."), [("Yes", "Mass does not depend on where you are."), ("No – his mass is more on the Moon", "Mass does not change.")])
U.q("F", "2.6", "O7", "Why is it better to time 10 swings of a pendulum and divide by 10 than to time 1 swing?", ("Reaction-time errors are shared over 10 swings, so the result is more accurate", "Starting and stopping errors become small compared with the total."), [("10 swings are faster", "They take longer, not shorter."), ("It is not better", "Timing many swings reduces the effect of reaction time.")])
V2 = U.V2
